function maximumScore(nums, k) {
  let left = k;
  let right = k;
  let minimum = nums[k];
  let best = nums[k];

  while (left > 0 || right < nums.length - 1) {
    const leftValue = left > 0 ? nums[left - 1] : 0;
    const rightValue = right < nums.length - 1 ? nums[right + 1] : 0;
    if (leftValue < rightValue) {
      right++;
      minimum = Math.min(minimum, nums[right]);
    } else {
      left--;
      minimum = Math.min(minimum, nums[left]);
    }
    best = Math.max(best, minimum * (right - left + 1));
  }
  return best;
}

