function maximumScore(nums, k) {
  let best = 0;
  for (let i = 0; i <= k; i++) {
    for (let j = k; j < nums.length; j++) {
      let low = Infinity;
      for (let t = i; t <= j; t++) low = Math.min(low, nums[t]);
      best = Math.max(best, low * (j - i + 1));
    }
  }
  return best;
}

