function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 8);
  const top = large ? 20000 : (rand() < 0.8 ? 6 : 20000);
  const shape = rand();
  let nums;
  if (shape < 0.25) {
    // A valley: values fall towards a random point and rise again, so the window must choose carefully.
    const bottom = int(0, n - 1);
    nums = Array.from({ length: n }, (_, i) => Math.max(1, top - Math.floor(Math.abs(i - bottom) * top / n) - int(0, Math.max(1, Math.floor(top / 10)))));
    nums = nums.map(v => top + 1 - v);
  } else if (shape < 0.4) {
    nums = Array.from({ length: n }, () => int(1, top));
    nums.sort((a, b) => a - b);
    if (rand() < 0.5) nums.reverse();
  } else {
    nums = Array.from({ length: n }, () => int(1, top));
  }
  nums = nums.map(v => Math.min(20000, Math.max(1, v)));
  return [nums, int(0, n - 1)];
}
